-- ========== KEY SYSTEM ONLY ==========

local Junkie = loadstring(game:HttpGet("https://jnkie.com/sdk/library.lua"))()
Junkie.service = "Dubu"
Junkie.identifier = "1030156"

local WindUI = loadstring(game:HttpGet("https://github.com/Footagesus/WindUI/releases/latest/download/main.lua"))()

WindUI:AddTheme({
    Name = "DubuPink",
    Accent = Color3.fromHex("#ff79b0"),
    Background = Color3.fromHex("#101010"),
    BackgroundTransparency = 0,
    Outline = Color3.fromHex("#ff79b0"),
    Text = Color3.fromHex("#ffffff"),
    Placeholder = Color3.fromHex("#e8d5db"),
    Button = Color3.fromHex("#ff79b0"),
    Icon = Color3.fromHex("#ff79b0"),
    Hover = Color3.fromHex("#ffcde1"),
    WindowBackground = Color3.fromHex("#101010"),
    WindowShadow = Color3.fromHex("#000000"),
    DialogBackground = Color3.fromHex("#101010"),
    DialogBackgroundTransparency = 0,
    DialogTitle = Color3.fromHex("#ffffff"),
    DialogContent = Color3.fromHex("#ffffff"),
    DialogIcon = Color3.fromHex("#ff79b0"),
    WindowTopbarButtonIcon = Color3.fromHex("#ff79b0"),
    WindowTopbarTitle = Color3.fromHex("#ffffff"),
    WindowTopbarAuthor = Color3.fromHex("#ffffff"),
    WindowTopbarIcon = Color3.fromHex("#ff79b0"),
    TabBackground = Color3.fromHex("#0b0b0b"),
    TabTitle = Color3.fromHex("#ffffff"),
    TabIcon = Color3.fromHex("#ff79b0"),
    ElementBackground = Color3.fromHex("#0b0b0b"),
    ElementTitle = Color3.fromHex("#ffffff"),
    ElementDesc = Color3.fromHex("#d1c7cf"),
    ElementIcon = Color3.fromHex("#ff79b0"),
    PopupBackground = Color3.fromHex("#101010"),
    PopupBackgroundTransparency = 0,
    PopupTitle = Color3.fromHex("#ffffff"),
    PopupContent = Color3.fromHex("#ffffff"),
    PopupIcon = Color3.fromHex("#ff79b0"),
    Toggle = Color3.fromHex("#ff79b0"),
    ToggleBar = Color3.fromHex("#ffffff"),
    Checkbox = Color3.fromHex("#ff79b0"),
    CheckboxIcon = Color3.fromHex("#ffffff"),
    Slider = Color3.fromHex("#ff79b0"),
    SliderThumb = Color3.fromHex("#ffffff"),
})

WindUI:SetTheme("DubuPink")

local Window

local function createProviderService(providerName, displayName)
    return {
        Name = displayName,
        Icon = "key",
        Args = {},
        New = function()
            local function verify(key)
                local oldProvider = Junkie.provider
                Junkie.provider = providerName
                local result = Junkie.check_key(key)
                Junkie.provider = oldProvider

                if result and result.valid then
                    if result.message == "KEYLESS" then
                        getgenv().SCRIPT_KEY = "KEYLESS"
                    else
                        getgenv().SCRIPT_KEY = key
                    end

                    local successMsg = result.message == "KEYLESS" and "Keyless mode" or "Key valid"
                    WindUI:Notify({
                        Title = "Key Validated",
                        Content = "Provider: " .. displayName .. "\n" .. successMsg,
                        Duration = 3
                    })
                    task.spawn(function()
                        task.wait(1)
                        Window:Destroy()
                    end)
                    return true, successMsg
                else
                    return false, "Invalid key"
                end
            end

            local function copy()
                local oldProvider = Junkie.provider
                Junkie.provider = providerName
                local link = Junkie.get_key_link()
                Junkie.provider = oldProvider
                if link and setclipboard then
                    setclipboard(link)
                    return true, "Link copied to clipboard"
                end
                return false, "Could not get key link"
            end

            return { Verify = verify, Copy = copy }
        end
    }
end

WindUI.Services.Linkvertise = createProviderService("Dubu", "Linkvertise")
WindUI.Services.Lootlabs   = createProviderService("LootlabsDubu", "Lootlabs")
WindUI.Services.Workink    = createProviderService("WorkinkDubu", "Workink")

Window = WindUI:CreateWindow({
    Title = "Dubu Hub",
    Icon = "key",
    Author = "Key Verification",
    Folder = "Dubuhub",
    Theme = "DubuPink",
    Size = UDim2.fromOffset(450, 300),
    MinSize = Vector2.new(400, 250),
    MaxSize = Vector2.new(500, 350),
    Resizable = false,
    HideSearchBar = true,
    ScrollBarEnabled = false,
    KeySystem = {
        Note = "Enter your Junkie key to continue.",
        SaveKey = true,
        API = {
            { Type = "Linkvertise" },
            { Type = "Lootlabs" },
            { Type = "Workink" },
        }
    }
})

local tab = Window:Tab({ Title = "Status", Icon = "check", Locked = false })
tab:Paragraph({ Title = "Welcome", Desc = "Key verified successfully." })

-- Wait for key then destroy window
while not getgenv().SCRIPT_KEY do
    task.wait(0.1)
end

Window:Destroy()

